"""Parse the saved Kazusa page into ../counts.tsv (D039).

Source: Codon Usage Database (Kazusa DNA Research Institute), entry
"Escherichia coli W3110 [gbbct]", species 316407: 4332 CDSs, 1372057 codons,
genetic code 1 (standard).

    https://www.kazusa.or.jp/codon/cgi-bin/showcodon.cgi?species=316407&aa=1&style=N

That page was captured on 2026-10-16 as ../raw/kazusa-316407-standard.html, so
the table can be re-derived from tracked files instead of from the live site.
This script reads only that capture; it contacts nothing.

The capture's <PRE> block holds 64 rows, `[triplet] [amino acid] [fraction]
[per thousand] ([count])`, with `U` for `T`. Here the rows are reordered into
standard table order - base order `T, C, A, G` for the first, second and third
base, the order of `ECOLI_K12_CODON_COUNTS` in `crates/core/src/codon_usage.rs`
- and `U` is written as `T`. The fraction and per-thousand columns are not
carried: the counts are the published data, and the derived columns follow from
them.

Run from the repository root with `python -I`:

    python -I tests/fixtures/codon-usage/reference/parse_kazusa.py
    python -I tests/fixtures/codon-usage/reference/parse_kazusa.py --check

Without --check, writes ../counts.tsv. With --check, regenerates the same text
in memory, compares it byte for byte with that tracked file, prints `OK
counts.tsv` or `DIFFERS counts.tsv` followed by the first differing line, exits
1 on a difference, and writes nothing (D039).
"""
import os
import re
import sys
import hashlib

BASES = "TCAG"  # standard table order, as in crates/core genetic_code.rs

HERE = os.path.dirname(os.path.abspath(__file__))
FIXTURE = os.path.dirname(HERE)
RAW = os.path.join(FIXTURE, "raw", "kazusa-316407-standard.html")
OUT = os.path.join(FIXTURE, "counts.tsv")

with open(RAW, "rb") as f:
    raw = f.read()
digest = hashlib.sha256(raw).hexdigest()

# The table block. Everything outside <PRE> is page furniture: form fields,
# GC percentages, links.
page = raw.decode("iso-8859-1")
start = page.index("<PRE>") + len("<PRE>")
end = page.index("</PRE>")
block = page[start:end]

# [triplet] [amino acid] [fraction] [frequency per thousand] ([count]).
# The count is right-aligned inside its parentheses, hence \s*.
ROW = re.compile(r"([UCAG]{3})\s+(\S)\s+([0-9.]+)\s+([0-9.]+)\s+\(\s*(\d+)\s*\)")
found = ROW.findall(block)
assert len(found) == 64, f"<PRE> block holds {len(found)} rows, not 64"

# The page orders its rows by pairs of first-two-bases in columns of four;
# standard order is one index per codon, so a duplicate or a missing codon
# would show up as a collision or a hole.
rows = {}
total = 0
for triplet, aa, _fraction, _per_thousand, count in found:
    codon = triplet.replace("U", "T")
    index = 0
    for ch in codon:
        assert ch in BASES, f"triplet {triplet} is not DNA"
        index = index * 4 + BASES.index(ch)
    assert index not in rows, f"codon {codon} appears twice"
    rows[index] = (codon, aa, int(count))
    total += int(count)

assert len(rows) == 64, f"{len(rows)} distinct codons, not 64"
assert total == 1372057, f"counts sum to {total}, not the published 1372057"

text = f"""#
# Codon counts for Escherichia coli W3110, a K-12 substrain (species 316407).
#
# Source: Codon Usage Database (Kazusa DNA Research Institute), entry
#   "Escherichia coli W3110 [gbbct]", species 316407: 4332 CDSs, 1372057 codons,
#   genetic code 1 (standard).
#   https://www.kazusa.or.jp/codon/cgi-bin/showcodon.cgi?species=316407&aa=1&style=N
#
# Capture: ../raw/kazusa-316407-standard.html, fetched from that URL on
#   2026-10-16, SHA-256 {digest}.
#
# `codon` is the page's triplet with U written as T, as DNA is written here.
# `amino_acid` is the page's one-letter code, `*` for stop. `count` is the
# raw number of occurrences over 4332 CDSs, the column in parentheses; the
# fraction and per-thousand columns are derived from it and not carried.
#
# Rows are in standard table order: base order T, C, A, G for the first,
# second and third base, the order of ECOLI_K12_CODON_COUNTS in
# crates/core/src/codon_usage.rs. Stop codons are included for completeness
# and are never selected as replacement codons.
#
# Generated by ../reference/parse_kazusa.py from the capture above - parsed,
# not transcribed. The counts sum to 1372057. Read by
# crates/core/tests/codon_usage_fixture.rs.
#
codon\tamino_acid\tcount
"""
for index in range(64):
    codon, aa, count = rows[index]
    text += f"{codon}\t{aa}\t{count}\n"

if "--check" in sys.argv[1:]:
    try:
        with open(OUT, "rb") as f:
            tracked = f.read()
    except FileNotFoundError:
        tracked = None
    if tracked == text.encode():
        print(f"OK {os.path.basename(OUT)}")
    else:
        print(f"DIFFERS {os.path.basename(OUT)}")
        old = tracked.decode().splitlines(True) if tracked is not None else []
        new = text.splitlines(True)
        for i in range(min(len(old), len(new))):
            if old[i] != new[i]:
                print(f"  line {i + 1}: tracked {old[i]!r} != generated {new[i]!r}")
                break
        else:
            i = min(len(old), len(new))
            if len(old) == len(new):
                print("  line-level comparison found no difference")
            else:
                where = "tracked" if len(old) > len(new) else "generated"
                extra = (old if len(old) > len(new) else new)[i]
                print(f"  line {i + 1}: only in {where}: {extra!r}")
        sys.exit(1)
else:
    with open(OUT, "w") as f:
        f.write(text)
    print("wrote", os.path.abspath(OUT))
